import 'package:cephalopod/features/game/presentation/models/difficulty_ui.dart';
import 'package:cephalopod/features/game/presentation/models/person_moves_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'opponent_ui.freezed.dart';

/// Who the person plays in a new game, with what is chosen for them. A
/// sealed class, so the computer always comes with its choices.
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
sealed class OpponentUi with _$OpponentUi {
  /// A friend on this device: nothing more to choose.
  const factory OpponentUi.friend() = FriendOpponentUi;

  /// The computer, playing at [difficulty], with the person moving first or
  /// second ([personMoves]).
  const factory OpponentUi.computer({
    required DifficultyUi difficulty,
    required PersonMovesUi personMoves,
  }) = ComputerOpponentUi;
}
